  var model = core.make({"id":"cico","kind":"drill","level":"resident","review":"ai_drafted","timeLimitSec":480,"title":{"en":"Failed intubation and CICO drill","hi":"विफल इंट्यूबेशन और CICO ड्रिल"},"scenario":{"en":"A 42-year-old man, 95 kg, has an elective hernia repair. Airway assessment looked normal. After propofol and rocuronium, the first Macintosh look shows no glottis. You are the anaesthetist. Teaching scenario, not a real patient.","hi":"42 वर्षीय पुरुष, 95 kg, की योजनाबद्ध हर्निया सर्जरी है। एयरवे जाँच सामान्य लगी थी। प्रोपोफोल और रोकुरोनियम के बाद पहली Macintosh लैरिंगोस्कोपी में ग्लॉटिस नहीं दिखता। आप एनेस्थेटिस्ट हैं। यह शिक्षण परिदृश्य है, असली मरीज़ नहीं।"},"sources":[{"label":"Frerk C, et al. Difficult Airway Society 2015 guidelines for management of unanticipated difficult intubation in adults. Br J Anaesth 2015;115:827-48","url":"https://academic.oup.com/bja/article/115/6/827/241440"},{"label":"Myatra SN, et al. All India Difficult Airway Association 2016 guidelines for the management of unanticipated difficult tracheal intubation in adults. Indian J Anaesth 2016;60:885-98","url":"https://pubmed.ncbi.nlm.nih.gov/28003690/"},{"label":"All India Difficult Airway Association 2025 guidelines for the management of unanticipated difficult airway in adults under general anaesthesia. Indian J Anaesth 2025;69:1117-41","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12643155/"}],"stages":[{"id":"firstlook","src":0,"timeSec":45,"vitals":{"hr":88,"bp":"124/76","spo2":99},"prompt":{"en":"First laryngoscopy shows only the epiglottis. SpO2 is 99%. What do you do?","hi":"पहली लैरिंगोस्कोपी में केवल एपिग्लॉटिस दिखता है। SpO2 99% है। आप क्या करेंगे?"},"options":[{"id":"a","correct":true,"critical":true,"next":"plana","text":{"en":"Call for help, oxygenate by mask, then optimise the next attempt: position, videolaryngoscope, bougie. Count every attempt.","hi":"मदद बुलाएँ, मास्क से ऑक्सीजन दें, फिर अगला प्रयास बेहतर करें: पोज़िशन, वीडियो लैरिंगोस्कोप, बूजी। हर प्रयास गिनें।"},"feedback":{"en":"Oxygenation comes before intubation. DAS 2015 limits laryngoscopy to 3 attempts, plus 1 by a more experienced colleague. Each attempt must be better than the last.","hi":"इंट्यूबेशन से पहले ऑक्सीजनेशन आता है। DAS 2015 लैरिंगोस्कोपी को 3 प्रयासों तक सीमित करता है, और 1 प्रयास अधिक अनुभवी सहकर्मी का। हर प्रयास पिछले से बेहतर हो।"}},{"id":"b","correct":false,"next":"trauma","text":{"en":"Keep trying with the same blade until the tube goes in.","hi":"उसी ब्लेड से तब तक कोशिश करते रहें जब तक ट्यूब न चली जाए।"},"feedback":{"en":"Repeated unchanged attempts cause swelling and bleeding. They turn a difficult airway into an impossible one.","hi":"बिना बदलाव के बार-बार प्रयास से सूजन और रक्तस्राव होता है। इससे कठिन एयरवे असंभव बन जाता है।"}},{"id":"c","correct":false,"next":"trauma","text":{"en":"Give a second dose of propofol and try again at once.","hi":"प्रोपोफोल की दूसरी खुराक दें और तुरंत फिर कोशिश करें।"},"feedback":{"en":"More drug does not fix the view. Oxygenate, call for help and change something before the next look.","hi":"और दवा से व्यू नहीं सुधरता। ऑक्सीजन दें, मदद बुलाएँ और अगली कोशिश से पहले कुछ बदलें।"}}]},{"id":"trauma","src":0,"timeSec":40,"vitals":{"hr":112,"bp":"140/88","spo2":90},"prompt":{"en":"After four rushed attempts there is blood in the pharynx and SpO2 is 90%. What now?","hi":"चार जल्दबाज़ी वाले प्रयासों के बाद ग्रसनी में खून है और SpO2 90% है। अब क्या?"},"options":[{"id":"a","correct":true,"next":"plana","text":{"en":"Stop laryngoscopy, call for help, suction and oxygenate by mask. Declare a difficult airway.","hi":"लैरिंगोस्कोपी रोकें, मदद बुलाएँ, सक्शन करें और मास्क से ऑक्सीजन दें। कठिन एयरवे घोषित करें।"},"feedback":{"en":"Late but right. Stop instrumenting, restore oxygen and get help before any further step.","hi":"देर से, पर सही। उपकरण डालना रोकें, ऑक्सीजन बहाल करें और आगे बढ़ने से पहले मदद लें।"}},{"id":"b","correct":false,"next":"plana","text":{"en":"Try a fifth time with a smaller tube.","hi":"छोटी ट्यूब से पाँचवीं बार कोशिश करें।"},"feedback":{"en":"The attempt limit is passed. More looks now only add trauma. Oxygenate and move on.","hi":"प्रयासों की सीमा पार हो चुकी है। अब और प्रयास केवल चोट बढ़ाएँगे। ऑक्सीजन दें और आगे बढ़ें।"}}]},{"id":"plana","src":0,"timeSec":45,"vitals":{"hr":96,"bp":"130/80","spo2":96},"prompt":{"en":"Your best attempts, including a videolaryngoscope and bougie, have failed. SpO2 is 96%. Next?","hi":"वीडियो लैरिंगोस्कोप और बूजी सहित आपके सर्वश्रेष्ठ प्रयास विफल हो गए। SpO2 96% है। अगला?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"Declare failed intubation and insert a second-generation supraglottic airway. Allow no more than 3 insertion attempts.","hi":"विफल इंट्यूबेशन घोषित करें और दूसरी पीढ़ी का सुप्राग्लॉटिक एयरवे डालें। 3 से अधिक प्रयास नहीं।"},"feedback":{"en":"Plan B is oxygenation through a supraglottic airway. Second-generation devices give a better seal and a drain channel for the stomach.","hi":"प्लान B सुप्राग्लॉटिक एयरवे से ऑक्सीजनेशन है। दूसरी पीढ़ी के उपकरण बेहतर सील और पेट के लिए ड्रेन चैनल देते हैं।"}},{"id":"b","correct":false,"text":{"en":"Try a blind nasal intubation.","hi":"अंधा नेज़ल इंट्यूबेशन करें।"},"feedback":{"en":"Blind techniques add trauma and delay. Rescue oxygenation with a supraglottic airway first.","hi":"अंधी तकनीकें चोट और देर बढ़ाती हैं। पहले सुप्राग्लॉटिक एयरवे से ऑक्सीजनेशन बचाएँ।"}},{"id":"c","correct":false,"text":{"en":"Go straight to a surgical airway while SpO2 is 96%.","hi":"SpO2 96% रहते हुए सीधे सर्जिकल एयरवे करें।"},"feedback":{"en":"He is still oxygenating. A supraglottic airway is the next plan, not the neck.","hi":"ऑक्सीजनेशन अभी हो रहा है। अगला प्लान सुप्राग्लॉटिक एयरवे है, गर्दन नहीं।"}}]},{"id":"planc","src":0,"timeSec":45,"vitals":{"hr":118,"bp":"146/90","spo2":84},"prompt":{"en":"Three supraglottic airway attempts give no seal and no capnography trace. SpO2 is 84%. What now?","hi":"सुप्राग्लॉटिक एयरवे के तीन प्रयासों में न सील बनी, न कैपनोग्राफ़ी ट्रेस आया। SpO2 84% है। अब क्या?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"One final best attempt at face mask ventilation: two people, oral and nasal airways, full neuromuscular block.","hi":"फ़ेस मास्क वेंटिलेशन का एक अंतिम सर्वश्रेष्ठ प्रयास: दो लोग, ओरल और नेज़ल एयरवे, पूरा न्यूरोमस्कुलर ब्लॉक।"},"feedback":{"en":"Plan C is a last try at mask oxygenation. If it works, wake the patient; sugammadex reverses rocuronium.","hi":"प्लान C मास्क से ऑक्सीजनेशन का अंतिम प्रयास है। सफल हो तो मरीज़ को जगाएँ; सुगामाडेक्स रोकुरोनियम को उलटता है।"}},{"id":"b","correct":false,"text":{"en":"Try a fourth and fifth supraglottic airway size.","hi":"सुप्राग्लॉटिक एयरवे का चौथा और पाँचवाँ साइज़ आज़माएँ।"},"feedback":{"en":"The device limit is reached. Further attempts waste the little oxygen reserve left.","hi":"उपकरण की सीमा पूरी हो चुकी है। और प्रयास बची हुई थोड़ी ऑक्सीजन बर्बाद करेंगे।"}}]},{"id":"declare","src":0,"timeSec":30,"vitals":{"hr":128,"bp":"150/92","spo2":72},"prompt":{"en":"Two-person mask ventilation fails. SpO2 is 72% and falling. What do you say and do?","hi":"दो व्यक्तियों से मास्क वेंटिलेशन विफल है। SpO2 72% है और गिर रहा है। आप क्या कहेंगे और करेंगे?"},"options":[{"id":"a","correct":true,"critical":true,"next":"fona","text":{"en":"Say aloud: this is CICO. Start front of neck access now, with full paralysis and 100% oxygen to the upper airway.","hi":"ज़ोर से कहें: यह CICO है। अभी फ़्रंट ऑफ़ नेक एक्सेस शुरू करें, पूरा पैरालिसिस रखें और ऊपरी एयरवे पर 100% ऑक्सीजन दें।"},"feedback":{"en":"Saying CICO aloud ends task fixation and moves the team to Plan D. DAS warns against neck access without full neuromuscular block.","hi":"CICO ज़ोर से कहने से एक ही काम पर अटकना रुकता है और टीम प्लान D पर जाती है। DAS पूरे न्यूरोमस्कुलर ब्लॉक के बिना गर्दन से एक्सेस न करने की चेतावनी देता है।"}},{"id":"b","correct":false,"next":"hypoxia","text":{"en":"Give sugammadex and wait for him to breathe.","hi":"सुगामाडेक्स दें और साँस लौटने का इंतज़ार करें।"},"feedback":{"en":"With a blocked upper airway, reversal alone may not restore oxygenation. Waiting costs the brain minutes it does not have.","hi":"ऊपरी एयरवे बंद हो तो केवल रिवर्सल से ऑक्सीजनेशन लौटे, यह ज़रूरी नहीं। इंतज़ार में दिमाग के कीमती मिनट जाते हैं।"}},{"id":"c","correct":false,"next":"hypoxia","text":{"en":"Have one more look with a different laryngoscope blade.","hi":"दूसरे ब्लेड से एक बार और लैरिंगोस्कोपी करें।"},"feedback":{"en":"This is task fixation, the commonest error in airway deaths. The neck is now the route.","hi":"यह एक ही काम पर अटकना है, एयरवे मौतों की सबसे आम गलती। अब रास्ता गर्दन है।"}}]},{"id":"hypoxia","src":0,"timeSec":30,"vitals":{"hr":48,"bp":"90/50","spo2":55},"prompt":{"en":"SpO2 is 55% and the heart rate has fallen to 48/min. What now?","hi":"SpO2 55% है और हृदय गति 48/min हो गई है। अब क्या?"},"options":[{"id":"a","correct":true,"next":"fona","text":{"en":"Declare CICO and perform front of neck access immediately.","hi":"CICO घोषित करें और तुरंत फ़्रंट ऑफ़ नेक एक्सेस करें।"},"feedback":{"en":"Bradycardia means severe hypoxia and impending arrest. Oxygen through the neck is the only fix.","hi":"ब्रैडीकार्डिया गंभीर हाइपोक्सिया और आने वाले अरेस्ट का संकेत है। गर्दन से ऑक्सीजन ही इलाज है।"}},{"id":"b","correct":false,"next":"fona","text":{"en":"Give atropine and keep mask ventilating.","hi":"एट्रोपिन दें और मास्क वेंटिलेशन जारी रखें।"},"feedback":{"en":"Atropine does not treat hypoxia. Secure oxygenation through the neck now.","hi":"एट्रोपिन हाइपोक्सिया का इलाज नहीं है। अभी गर्दन से ऑक्सीजनेशन सुनिश्चित करें।"}}]},{"id":"fona","src":0,"timeSec":60,"vitals":{"hr":120,"spo2":68},"prompt":{"en":"The cricothyroid membrane is palpable. Which technique and kit?","hi":"क्रिकोथायरॉइड मेम्ब्रेन महसूस हो रहा है। कौन सी तकनीक और सामान?"},"options":[{"id":"a","correct":true,"critical":true,"next":"impalpable","text":{"en":"Scalpel cricothyroidotomy: number 10 blade, stab, twist, bougie, then a 6.0 mm cuffed tube.","hi":"स्कैल्पल क्रिकोथायरॉइडोटॉमी: नंबर 10 ब्लेड, स्टैब, ट्विस्ट, बूजी, फिर 6.0 mm कफ़ वाली ट्यूब।"},"feedback":{"en":"DAS 2015 and AIDAA 2025 both prefer the scalpel technique. A cuffed tube protects the lungs and allows normal ventilation.","hi":"DAS 2015 और AIDAA 2025 दोनों स्कैल्पल तकनीक को प्राथमिकता देते हैं। कफ़ वाली ट्यूब फेफड़ों को बचाती है और सामान्य वेंटिलेशन देती है।"}},{"id":"b","correct":false,"next":"impalpable","text":{"en":"A 14 G cannula through the membrane with jet ventilation by the operator in training.","hi":"मेम्ब्रेन से 14 G कैनुला और प्रशिक्षु द्वारा जेट वेंटिलेशन।"},"feedback":{"en":"Narrow cannula techniques fail often and risk barotrauma. Use the scalpel route.","hi":"पतली कैनुला तकनीकें अक्सर विफल होती हैं और बैरोट्रॉमा का खतरा है। स्कैल्पल का रास्ता अपनाएँ।"}}]},{"id":"impalpable","src":0,"timeSec":45,"prompt":{"en":"Teaching point. If his neck had been fat and the membrane impalpable, what would you do?","hi":"सीखने का बिंदु। अगर गर्दन मोटी होती और मेम्ब्रेन महसूस न होता, तो आप क्या करते?"},"options":[{"id":"a","correct":true,"next":"confirm","text":{"en":"Make an 8 to 10 cm vertical midline skin incision, find the membrane by blunt dissection, then proceed as before.","hi":"8 से 10 cm का ऊर्ध्वाधर मध्य रेखा त्वचा चीरा लगाएँ, ब्लंट डिसेक्शन से मेम्ब्रेन खोजें, फिर पहले जैसा करें।"},"feedback":{"en":"DAS 2015 advises a vertical incision when the membrane cannot be felt. Fingers then locate the larynx.","hi":"मेम्ब्रेन महसूस न हो तो DAS 2015 ऊर्ध्वाधर चीरा सलाह देता है। फिर उँगलियों से लैरिंक्स खोजा जाता है।"}},{"id":"b","correct":false,"next":"confirm","text":{"en":"Wait for the surgeon to perform a formal tracheostomy.","hi":"औपचारिक ट्रेकियोस्टॉमी के लिए सर्जन का इंतज़ार करें।"},"feedback":{"en":"A formal tracheostomy is too slow in CICO. The anaesthetist must be ready to cut.","hi":"CICO में औपचारिक ट्रेकियोस्टॉमी बहुत धीमी है। एनेस्थेटिस्ट को चीरा लगाने के लिए तैयार रहना चाहिए।"}}]},{"id":"confirm","src":1,"timeSec":45,"vitals":{"hr":104,"bp":"136/84","spo2":93,"etco2":{"label":{"en":"EtCO2 (mmHg)","hi":"EtCO2 (mmHg)"},"value":44}},"prompt":{"en":"The tube is in and SpO2 is rising. What completes the job?","hi":"ट्यूब अंदर है और SpO2 बढ़ रहा है। काम पूरा करने के लिए क्या करें?"},"options":[{"id":"a","correct":true,"critical":true,"next":"end","text":{"en":"Inflate the cuff, confirm with waveform capnography, secure the tube, and plan surgical review. Later document and issue an airway alert.","hi":"कफ़ फुलाएँ, वेवफ़ॉर्म कैपनोग्राफ़ी से पुष्टि करें, ट्यूब बाँधें और सर्जिकल समीक्षा तय करें। बाद में दस्तावेज़ बनाएँ और एयरवे अलर्ट दें।"},"feedback":{"en":"Capnography proves tracheal placement. AIDAA asks for counselling and a difficult airway alert form so the next team is warned.","hi":"कैपनोग्राफ़ी श्वासनली में ट्यूब साबित करती है। AIDAA परामर्श और कठिन एयरवे अलर्ट फ़ॉर्म माँगता है ताकि अगली टीम सावधान रहे।"}},{"id":"b","correct":false,"next":"end","text":{"en":"Trust the chest movement and go on with the hernia repair.","hi":"छाती की गति पर भरोसा करें और हर्निया सर्जरी जारी रखें।"},"feedback":{"en":"Chest movement can mislead. Confirm with capnography, and postpone elective surgery after a CICO event.","hi":"छाती की गति धोखा दे सकती है। कैपनोग्राफ़ी से पुष्टि करें, और CICO के बाद योजनाबद्ध सर्जरी टालें।"}}]}]});
